"""Fully observable M4 synthetic operator experience.

Provides a dedicated page where M4 automatically selects an opening, ranks the
customer population, exposes her decision path, visibly moves candidates through
selection, and activates the isolated synthetic recovery engine. No external
messages are sent in the demo account.
"""
from fastapi import Request
from fastapi.responses import HTMLResponse

import app as core


@core.app.get("/m4-operator-live", response_class=HTMLResponse)
def m4_operator_live(request: Request):
    user, redirect = core.login_required_redirect(request)
    if redirect:
        return redirect

    html = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>M4 Live Operator</title>
<style>
:root{--bg:#060806;--panel:#0b0f0b;--line:#253025;--ink:#edf5e8;--muted:#788276;--g:#a6ff2e}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% 15%,rgba(166,255,46,.06),transparent 28%),var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif}.shell{max-width:1320px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px}.brand{letter-spacing:.16em;font-weight:800}.brand small{display:block;color:var(--muted);font:600 9px ui-monospace,monospace;margin-top:5px}.controls{display:flex;gap:8px}.btn{border:1px solid var(--g);background:var(--g);color:#071007;padding:11px 14px;font-weight:900;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;text-decoration:none}.btn.alt{background:transparent;color:var(--ink);border-color:#465246}.hero{display:grid;grid-template-columns:1fr 310px;gap:38px;padding:42px 0 24px}.hero h1{font-size:clamp(42px,6vw,76px);line-height:.92;letter-spacing:-.05em;margin:8px 0 14px}.hero p{color:#aab2a6;max-width:760px;line-height:1.6}.m4{min-height:180px;border:1px solid var(--line);display:grid;place-items:center;background:radial-gradient(circle,rgba(166,255,46,.10),rgba(166,255,46,.015) 46%,transparent 72%);position:relative;overflow:hidden}.cell{width:62px;height:62px;border-radius:46% 54% 53% 47%;background:rgba(166,255,46,.16);box-shadow:0 0 24px rgba(166,255,46,.55),0 0 80px rgba(166,255,46,.16);animation:breathe 3.4s ease-in-out infinite}.m4.thinking .cell{animation-duration:.9s;box-shadow:0 0 35px rgba(166,255,46,.75),0 0 100px rgba(166,255,46,.25)}.m4.acting .cell{transform:scale(1.15);box-shadow:0 0 44px rgba(166,255,46,.95),0 0 120px rgba(166,255,46,.35)}@keyframes breathe{50%{transform:scale(1.12) rotate(8deg)}}.m4 label{position:absolute;bottom:16px;font:700 9px ui-monospace,monospace;letter-spacing:.13em;color:#bfe89c;text-transform:uppercase}.grid{display:grid;grid-template-columns:300px 1fr 330px;gap:1px;background:var(--line);border:1px solid var(--line)}.pane{background:var(--panel);padding:20px;min-height:570px}.ey{color:var(--g);font:700 9px ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase}.pane h2{margin:8px 0 6px;font-size:21px}.sub{color:var(--muted);font-size:12px;line-height:1.5;margin-bottom:16px}.opening,.person,.node{border:1px solid #2d392d;background:#0e140e;padding:12px;margin-bottom:8px}.opening.active{border-color:var(--g);box-shadow:inset 3px 0 0 var(--g)}.opening b,.person b{display:block;font-size:12px}.opening span,.person span{color:var(--muted);font:600 9px ui-monospace,monospace;display:block;margin-top:5px}.lanes{display:grid;grid-template-columns:1fr 1fr;gap:14px}.lane{border:1px dashed #303b30;min-height:210px;padding:12px}.lane h3{margin:0 0 10px;font-size:11px;letter-spacing:.09em;text-transform:uppercase;color:#9da996}.person{transition:.35s ease}.person.focus{border-color:var(--g);background:#101b0d}.score{color:var(--g)!important}.tree{display:grid;gap:7px}.node{opacity:.34;transition:.3s}.node.active{opacity:1;border-color:var(--g);background:#101a0f}.node.done{opacity:.72}.node strong{font-size:11px}.node small{display:block;color:var(--muted);margin-top:4px}.log{margin-top:14px;border:1px solid #263026;background:#070a07;padding:13px;min-height:145px;white-space:pre-wrap;font:500 10px/1.65 ui-monospace,monospace;color:#b9c6b4}.result{margin-top:12px;padding:13px;border-left:2px solid var(--g);background:#10170f;color:#cce1c3;font-size:12px;display:none}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:0 0 18px}.metric{border:1px solid var(--line);padding:11px;background:#0a0d0a}.metric b{font-size:18px}.metric small{display:block;color:var(--muted);font-size:9px;margin-top:3px}@media(max-width:980px){.grid{grid-template-columns:1fr}.hero{grid-template-columns:1fr}.pane{min-height:auto}.metrics{grid-template-columns:repeat(2,1fr)}}
</style></head><body><div class="shell">
<div class="top"><div class="brand">EMPTY CHAIR<small>M4 // LIVE OPERATING VIEW</small></div><div class="controls"><button id="run" class="btn">Run autonomous recovery</button><a class="btn alt" href="/demo">Demo home</a></div></div>
<section class="hero"><div><div class="ey">Observe → filter → predict → choose → act → learn</div><h1>Watch M4 work.</h1><p>M4 chooses the highest-value opening, narrows the customer population, exposes each decision gate, selects the best next customer, then activates Empty Chair. In the demo account, every recipient and outcome is synthetic and no external message is sent.</p></div><div id="m4" class="m4"><div class="cell"></div><label id="m4state">observing shop state</label></div></section>
<div class="metrics"><div class="metric"><b id="mc">—</b><small>customers observed</small></div><div class="metric"><b id="mo">—</b><small>open gaps</small></div><div class="metric"><b id="mev">—</b><small>top expected value</small></div><div class="metric"><b id="mscore">—</b><small>M4 queue score</small></div></div>
<section class="grid"><div class="pane"><div class="ey">01 // Inventory</div><h2>What M4 sees</h2><div class="sub">She starts with perishable chair time, not a customer list.</div><div id="openings">Loading…</div></div>
<div class="pane"><div class="ey">02 // Customer movement</div><h2>Population → shortlist → action</h2><div class="sub">The visible cards are leading candidates from the larger consented population.</div><div class="lanes"><div class="lane"><h3>Candidate pool</h3><div id="pool"></div></div><div class="lane"><h3>M4 shortlist</h3><div id="short"></div></div></div><div id="result" class="result"></div><div id="log" class="log">M4 // waiting for autonomous run</div></div>
<div class="pane"><div class="ey">03 // Decision tree</div><h2>Why she moves</h2><div class="sub">These are the actual gates used to narrow and order demand.</div><div id="tree" class="tree"><div class="node"><strong>1. Opening value</strong><small>Which gap is most economically urgent?</small></div><div class="node"><strong>2. Consent + eligibility</strong><small>Who can safely be contacted?</small></div><div class="node"><strong>3. Artist fit</strong><small>Does the customer prefer this artist?</small></div><div class="node"><strong>4. Style fit</strong><small>Does the opening match demonstrated preference?</small></div><div class="node"><strong>5. Budget fit</strong><small>Is this price near historical spend?</small></div><div class="node"><strong>6. Incremental uplift</strong><small>Who is more likely to book because of the intervention?</small></div><div class="node"><strong>7. Confidence</strong><small>How much evidence supports the prediction?</small></div><div class="node"><strong>8. Sequential action</strong><small>Contact the best candidate first, then learn from outcome.</small></div></div></div></section>
</div><script>
(()=>{const run=document.getElementById('run'),m4=document.getElementById('m4'),m4state=document.getElementById('m4state'),openings=document.getElementById('openings'),pool=document.getElementById('pool'),short=document.getElementById('short'),log=document.getElementById('log'),result=document.getElementById('result');let data=null,selected=null,ranked=[];const sleep=ms=>new Promise(r=>setTimeout(r,ms));function state(s,mode='thinking'){m4.className='m4 '+mode;m4state.textContent=s;log.textContent+='\n'+s}function step(n){document.querySelectorAll('.node').forEach((x,i)=>{x.classList.toggle('active',i===n);if(i<n)x.classList.add('done')})}async function load(allowReset=true){const r=await fetch('/api/m4/operator/status',{cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Could not load');if((!j.openings||!j.openings.length)&&j.synthetic&&allowReset){state('No open gaps found. Resetting synthetic shop state.');const rr=await fetch('/api/m4/operator/reset-synthetic',{method:'POST',cache:'no-store'}),rj=await rr.json();if(!rr.ok)throw Error(rj.error||'Could not reset synthetic demo');return load(false)}data=j;document.getElementById('mc').textContent=(j.dataset&&j.dataset.customers)||'0';document.getElementById('mo').textContent=(j.openings||[]).length;openings.innerHTML='';if(!j.openings||!j.openings.length){openings.innerHTML='<div class="opening"><b>No OPEN gaps available</b><span>Reset the demo or create an opening, then run M4 again.</span></div>';run.disabled=true;state('Waiting for an OPEN booking gap','');return}run.disabled=false;j.openings.forEach(o=>{const d=document.createElement('div');d.className='opening';d.dataset.id=o.id;d.innerHTML=`<b>${o.style||'Open chair'} · $${Number(o.price||0).toLocaleString()}</b><span>${o.date} ${o.start_time}–${o.end_time||''} · ${o.artist_id}</span>`;openings.appendChild(d)})}async function preview(o){const f=new FormData();f.append('opening_id',o.id);const r=await fetch('/api/m4/operator/preview',{method:'POST',body:f,cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Preview failed');return j}function card(c){const d=document.createElement('div');d.className='person';d.dataset.id=c.customer_id;d.innerHTML=`<b>${c.name||c.customer_id}</b><span>booking ${Math.round(c.booking_probability*100)}% · uplift ${Math.round(c.incremental_uplift*100)}%</span><span class="score">queue ${c.queue_score} · EV $${Number(c.expected_value||0).toFixed(0)}</span>`;return d}
run.onclick=async()=>{run.disabled=true;result.style.display='none';pool.innerHTML='';short.innerHTML='';log.textContent='M4 // autonomous run started';document.querySelectorAll('.node').forEach(x=>x.classList.remove('active','done'));try{if(!data||!data.openings||!data.openings.length)await load();if(!data||!data.openings||!data.openings.length)throw Error('No OPEN booking gaps are available for M4 to operate on.');step(0);state('Scanning open chair inventory');await sleep(700);selected=[...data.openings].sort((a,b)=>Number(b.price||0)-Number(a.price||0))[0];if(!selected)throw Error('M4 could not select an opening because the current inventory is empty.');document.querySelectorAll('.opening').forEach(x=>x.classList.toggle('active',x.dataset.id===selected.id));state(`Selected ${selected.style||'opening'} at $${Number(selected.price||0).toLocaleString()} — highest-value current gap`);await sleep(800);step(1);state('Filtering to consented, eligible customer demand');const p=await preview(selected);ranked=p.m4_top_candidates||[];document.getElementById('mc').textContent=p.consented_candidates;ranked.forEach(c=>pool.appendChild(card(c)));await sleep(900);if(!ranked.length)throw Error('No eligible modeled customers were returned for this opening.');const labels=['','','Testing artist affinity','Testing style affinity','Testing price-to-spend fit','Estimating incremental booking uplift','Calibrating confidence from historical evidence'];for(let s=2;s<=6;s++){step(s);state(labels[s]);await sleep(600);if(ranked[s-2]){const el=pool.querySelector(`[data-id="${ranked[s-2].customer_id}"]`);if(el){el.classList.add('focus');await sleep(260);short.appendChild(el);el.classList.remove('focus')}}}ranked.slice(5).forEach(c=>{const el=pool.querySelector(`[data-id="${c.customer_id}"]`);if(el)short.appendChild(el)});const top=ranked[0];document.getElementById('mev').textContent='$'+Number(top.expected_value||0).toFixed(0);document.getElementById('mscore').textContent=top.queue_score;const topEl=short.querySelector(`[data-id="${top.customer_id}"]`);if(topEl)topEl.classList.add('focus');step(7);state(`Choosing ${top.name||top.customer_id} first and activating sequential recovery`,'acting');await sleep(900);const f=new FormData();f.append('opening_id',selected.id);const r=await fetch('/api/m4/operator/activate',{method:'POST',body:f,cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Activation failed');state('Recovery activated. Waiting for outcome signal, then the model updates.','acting');result.style.display='block';result.innerHTML=`<b>ACTION COMPLETE</b><br>${j.message}<br><br>First customer: ${top.name||top.customer_id}<br>External delivery: ${j.synthetic?'suppressed — synthetic demo':'production safeguards apply'}`;await sleep(1000);state('Observing outcome. Next action depends on accept, decline, expiry, or booking.','');await load()}catch(e){state('Interrupted: '+e.message,'');result.style.display='block';result.textContent=e.message}finally{if(data&&data.openings&&data.openings.length)run.disabled=false}};load().catch(e=>{log.textContent=e.message;run.disabled=true})})();
</script></body></html>'''
    return HTMLResponse(html, headers={"Cache-Control": "no-store"})
